-- V3 additive migration: eleven new tables; preserves existing data.
SET NAMES utf8mb4;
USE hw_learning;
CREATE TABLE IF NOT EXISTS teaching_class(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,teacher_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,semester VARCHAR(40) NOT NULL,description VARCHAR(1000) NULL,join_code VARCHAR(24) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',version INT NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,UNIQUE KEY uk_class_code(join_code),KEY idx_class_teacher(teacher_id,status,id),CHECK(status IN('ACTIVE','CLOSED')),CHECK(version>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS class_member(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,class_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,enrollment_id BIGINT UNSIGNED NOT NULL,status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE',joined_at DATETIME(3) NOT NULL,UNIQUE KEY uk_class_student(class_id,student_id),KEY idx_member_student(student_id,id),CHECK(status IN('ACTIVE','LEFT')),FOREIGN KEY(class_id) REFERENCES teaching_class(id) ON DELETE RESTRICT,FOREIGN KEY(enrollment_id) REFERENCES course_enrollment(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reading_annotation(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,enrollment_id BIGINT UNSIGNED NOT NULL,chapter_id BIGINT UNSIGNED NOT NULL,start_offset INT NOT NULL,end_offset INT NOT NULL,quote_text VARCHAR(500) NOT NULL,source_hash CHAR(64) NOT NULL,comment VARCHAR(1000) NOT NULL,color VARCHAR(10) NOT NULL,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,KEY idx_annotation_owner(student_id,enrollment_id,chapter_id,id),FOREIGN KEY(enrollment_id) REFERENCES course_enrollment(id) ON DELETE RESTRICT,CHECK(start_offset>=0 AND end_offset>start_offset),CHECK(color IN('RED','PINE','GOLD'))) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inbox_receipt(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(180) NOT NULL,read_at DATETIME(3) NOT NULL,UNIQUE KEY uk_receipt_user_event(user_id,event_key)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS quiz_attempt(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quiz_id BIGINT UNSIGNED NOT NULL,course_id BIGINT UNSIGNED NOT NULL,chapter_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,score INT NOT NULL,total INT NOT NULL,completed_at DATETIME(3) NOT NULL,UNIQUE KEY uk_attempt_student_quiz(student_id,quiz_id),KEY idx_attempt_course(course_id,student_id,id),CHECK(total>0 AND score>=0 AND score<=total)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS quiz_attempt_item(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,prompt TEXT NOT NULL,option_a VARCHAR(500) NOT NULL,option_b VARCHAR(500) NOT NULL,option_c VARCHAR(500) NOT NULL,option_d VARCHAR(500) NOT NULL,selected_option CHAR(1) NOT NULL,correct_option CHAR(1) NOT NULL,explanation VARCHAR(2000) NULL,correct BOOLEAN NOT NULL,UNIQUE KEY uk_attempt_question(attempt_id,question_id),FOREIGN KEY(attempt_id) REFERENCES quiz_attempt(id) ON DELETE RESTRICT,CHECK(selected_option IN('A','B','C','D')),CHECK(correct_option IN('A','B','C','D')),CHECK(correct IN(0,1))) ENGINE=InnoDB;
USE hw_course;
CREATE TABLE IF NOT EXISTS course_resource(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,chapter_id BIGINT UNSIGNED NULL,title VARCHAR(100) NOT NULL,description VARCHAR(1000) NULL,original_name VARCHAR(160) NOT NULL,storage_name VARCHAR(60) NOT NULL,mime_type VARCHAR(80) NOT NULL,bytes BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at DATETIME(3) NOT NULL,KEY idx_resource_course(course_id,chapter_id,status,id),FOREIGN KEY(course_id) REFERENCES course(id) ON DELETE RESTRICT,FOREIGN KEY(chapter_id) REFERENCES course_chapter(id) ON DELETE RESTRICT,CHECK(status IN('ACTIVE','REMOVED')),CHECK(bytes>0 AND bytes<=20971520)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chapter_quiz(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,chapter_id BIGINT UNSIGNED NOT NULL,title VARCHAR(100) NOT NULL,instructions VARCHAR(2000) NULL,status VARCHAR(16) NOT NULL DEFAULT 'DRAFT',version INT NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,KEY idx_quiz_course(course_id,chapter_id,status,id),FOREIGN KEY(course_id) REFERENCES course(id) ON DELETE RESTRICT,FOREIGN KEY(chapter_id) REFERENCES course_chapter(id) ON DELETE RESTRICT,CHECK(status IN('DRAFT','PUBLISHED','ARCHIVED')),CHECK(version>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS quiz_question(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quiz_id BIGINT UNSIGNED NOT NULL,prompt TEXT NOT NULL,option_a VARCHAR(500) NOT NULL,option_b VARCHAR(500) NOT NULL,option_c VARCHAR(500) NOT NULL,option_d VARCHAR(500) NOT NULL,correct_option CHAR(1) NOT NULL,explanation VARCHAR(2000) NULL,sort_no INT NOT NULL,UNIQUE KEY uk_quiz_sort(quiz_id,sort_no),FOREIGN KEY(quiz_id) REFERENCES chapter_quiz(id) ON DELETE RESTRICT,CHECK(correct_option IN('A','B','C','D')),CHECK(sort_no>0)) ENGINE=InnoDB;
USE hw_assignment;
CREATE TABLE IF NOT EXISTS assignment_draft(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,assignment_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,answer_text TEXT NOT NULL,version INT NOT NULL DEFAULT 0,updated_at DATETIME(3) NOT NULL,UNIQUE KEY uk_draft_assignment_student(assignment_id,student_id),FOREIGN KEY(assignment_id) REFERENCES assignment_task(id) ON DELETE RESTRICT,CHECK(version>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assignment_grade_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,submission_id BIGINT UNSIGNED NOT NULL,teacher_id BIGINT UNSIGNED NOT NULL,submission_version INT NOT NULL,score DECIMAL(5,2) NOT NULL,comment TEXT NULL,graded_at DATETIME(3) NOT NULL,UNIQUE KEY uk_history_submission_version(submission_id,submission_version),FOREIGN KEY(submission_id) REFERENCES assignment_submission(id) ON DELETE RESTRICT,CHECK(score>=0 AND score<=100),CHECK(submission_version>=0)) ENGINE=InnoDB;
INSERT INTO assignment_grade_history(submission_id,teacher_id,submission_version,score,comment,graded_at) SELECT g.submission_id,g.teacher_id,s.version,g.score,g.comment,g.graded_at FROM assignment_grade g JOIN assignment_submission s ON s.id=g.submission_id WHERE NOT EXISTS(SELECT 1 FROM assignment_grade_history h WHERE h.submission_id=s.id);
